// Build ONE OpenWA bulk batch (max 100) for this campaign run.
// OpenWA runs separate batches concurrently, so one batch per run keeps the pacing real;
// re-running the same campaign continues where it stopped (already-sent contacts are skipped).
const f = $('Campaign Form').first().json;
const slug = s => String(s || '').trim().toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '');
const list = slug(f.list_name);
const campaign = slug(f.campaign_name);
const message = String(f.message || '').trim();
const live = String(f.mode || '').startsWith('Live');
const cap = Math.min(Math.max(parseInt(f.batch_size, 10) || 50, 1), 100);
const delaySec = Math.min(Math.max(parseInt(f.delay_seconds, 10) || 10, 5), 60);
const tag = String(f.tag_filter || '').trim().toLowerCase();
if (!list || !campaign) throw new Error('List name and campaign name are required.');
if (!message) throw new Error('Message is empty.');

const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
const eligible = rows.filter(r =>
  r.list === list && r.opted_in === true && r.on_whatsapp === true &&
  (!tag || String(r.tags || '').toLowerCase().split(/[,;|]/).map(t => t.trim()).includes(tag)));
const pending = eligible.filter(r => r.last_campaign !== campaign);
if (!rows.length) throw new Error(`List "${list}" has no contacts. Upload it first.`);
if (!eligible.length) throw new Error(`No opted-in WhatsApp contacts in "${list}"${tag ? ` with tag "${tag}"` : ''}.`);
if (live && !pending.length) throw new Error(`Campaign "${campaign}" already reached all ${eligible.length} contacts in "${list}".`);

const vars = r => {
  let extra = {}; try { extra = JSON.parse(r.extra || '{}'); } catch (e) {}
  const first = String(r.name || '').split(/\s+/)[0];
  return { ...extra, name: r.name || 'there', first_name: first || 'there', phone: r.phone };
};
const chatId = r => r.whatsapp_id || `${r.phone}@c.us`;

let targets;
if (live) {
  targets = pending.slice(0, cap);
} else {
  const testPhone = String(f.test_number || '').replace(/\D/g, '');
  if (testPhone.length < 10) throw new Error('Test mode needs your own WhatsApp number (with country code).');
  const sample = (pending[0] || eligible[0]);
  targets = [{ ...sample, phone: testPhone, whatsapp_id: `${testPhone}@c.us` }];
}

const batchId = `${campaign}-${live ? 'live' : 'test'}-${Date.now()}`;
return [{ json: {
  live, list, campaign, batchId,
  recipients: live ? targets.map(t => t.key) : [],
  remainingAfter: live ? pending.length - targets.length : pending.length,
  etaMinutes: Math.ceil(targets.length * (delaySec + 1) / 60),
  payload: {
    batchId,
    messages: targets.map(t => ({ chatId: chatId(t), type: 'text', content: { text: message }, variables: vars(t) })),
    options: { delayBetweenMessages: delaySec * 1000, randomizeDelay: true, stopOnError: false },
  },
} }];

