// After OpenWA accepted a LIVE batch, emit one item per recipient so the contacts table
// records this campaign (re-runs then skip them). Test runs mark nothing.
const b = $('Build Campaign Batch').first().json;
if (!b.live) return [];
const now = new Date().toISOString();
return b.recipients.map((key, i) => ({ json: { key, last_campaign: b.campaign, last_sent_at: now }, pairedItem: { item: 0 } }));
